<script>
import debounce from 'lodash/debounce';
import isEqual from 'lodash/isEqual';
import { mapGetters, mapState } from 'vuex';
import {
  mapPref,
  FAVORITE_TYPES
} from '@shell/store/prefs';
import { getVersionInfo } from '@shell/utils/version';
import {
  addObjects, replaceWith, clear, addObject, sameContents
} from '@shell/utils/array';
import { sortBy } from '@shell/utils/sort';
import { ucFirst } from '@shell/utils/string';

import { HCI, UI, SCHEMA } from '@shell/config/types';
import { HARVESTER_NAME as HARVESTER } from '@shell/config/features';
import { NAME as EXPLORER } from '@shell/config/product/explorer';
import { TYPE_MODES } from '@shell/store/type-map';
import { NAME as NAVLINKS } from '@shell/config/product/navlinks';
import Group from '@shell/components/nav/Group';
import LocaleSelector from '@shell/components/LocaleSelector';

export default {
  name:       'SideNav',
  components: { Group, LocaleSelector },
  data() {
    return {
      groups:        [],
      gettingGroups: false
    };
  },

  created() {
    this.queueUpdate = debounce(this.getGroups, 500);
    this.getGroups();
  },

  mounted() {
    this.$nextTick(() => this.syncNav());
  },

  watch: {
    allSchemasIds(a, b) {
      if ( !sameContents(a, b) ) {
        this.queueUpdate();
      }
    },

    allNavLinksIds(a, b) {
      if ( !sameContents(a, b) ) {
        this.queueUpdate();
      }
    },

    favoriteTypes(a, b) {
      if ( !isEqual(a, b) ) {
        this.queueUpdate();
      }
    },

    locale(a, b) {
      if ( !isEqual(a, b) ) {
        this.getGroups();
      }
    },

    namespaceMode(a, b) {
      if ( a !== b ) {
        this.queueUpdate();
      }
    },

    namespaces(a, b) {
      if ( !isEqual(a, b) ) {
        this.queueUpdate();
      }
    },

    clusterReady(a, b) {
      if ( !isEqual(a, b) ) {
        this.getGroups();
      }
    },

    rootProduct(a, b) {
      if (a?.name !== b?.name) {
        this.getGroups();
      }
    },

    $route(a, b) {
      this.$nextTick(() => this.syncNav());
    },
  },

  computed: {
    ...mapState(['managementReady', 'clusterReady']),
    ...mapGetters(['isStandaloneHarvester', 'productId', 'clusterId', 'currentProduct', 'rootProduct', 'isSingleProduct', 'namespaceMode', 'isExplorer', 'isVirtualCluster']),
    ...mapGetters({ locale: 'i18n/selectedLocaleLabel', hasMultipleLocales: 'i18n/hasMultipleLocales' }),
    ...mapGetters('type-map', ['activeProducts']),

    favoriteTypes: mapPref(FAVORITE_TYPES),

    supportLink() {
      const product = this.rootProduct;

      if (product?.supportRoute) {
        return { ...product.supportRoute, params: { ...product.supportRoute.params, cluster: this.clusterId } };
      }

      return { name: `c-cluster-${ product?.name }-support` };
    },

    displayVersion() {
      if (this.isSingleProduct?.getVersionInfo) {
        return this.isSingleProduct?.getVersionInfo(this.$store);
      }
      const { displayVersion } = getVersionInfo(this.$store);

      return displayVersion;
    },

    singleProductAbout() {
      return this.isSingleProduct?.aboutPage;
    },

    harvesterVersion() {
      return this.$store.getters['cluster/byId'](HCI.SETTING, 'server-version')?.value || 'unknown';
    },

    showProductFooter() {
      if (this.isVirtualProduct) {
        return true;
      } else {
        return false;
      }
    },

    isVirtualProduct() {
      return this.rootProduct.name === HARVESTER;
    },

    allNavLinks() {
      if ( !this.clusterId || !this.$store.getters['cluster/schemaFor'](UI.NAV_LINK) ) {
        return [];
      }

      return this.$store.getters['cluster/all'](UI.NAV_LINK);
    },

    allSchemasIds() {
      const managementReady = this.managementReady;
      const product = this.currentProduct;

      if ( !managementReady || !product ) {
        return [];
      }

      return this.$store.getters[`${ product.inStore }/all`](SCHEMA).map((s) => s.id).sort();
    },

    namespaces() {
      return this.$store.getters['activeNamespaceCache'];
    },

    allNavLinksIds() {
      return this.allNavLinks.map((a) => a.id);
    },
  },

  methods: {
    getGroups() {
      if ( this.gettingGroups ) {
        return;
      }
      this.gettingGroups = true;

      if ( !this.clusterReady ) {
        clear(this.groups);
        this.gettingGroups = false;

        return;
      }

      const currentProduct = this.$store.getters['productId'];
      const namespaceMode = 'both';
      const out = [];
      const loadProducts = this.isExplorer ? [EXPLORER] : [];

      const productMap = this.activeProducts.reduce((acc, p) => {
        return { ...acc, [p.name]: p };
      }, {});

      if ( this.isExplorer ) {
        for ( const product of this.activeProducts ) {
          if ( product.inStore === 'cluster' ) {
            addObject(loadProducts, product.name);
          }
        }
      }

      addObject(loadProducts, currentProduct);

      this.getProductsGroups(out, loadProducts, namespaceMode, productMap);
      this.getExplorerGroups(out);

      replaceWith(this.groups, ...sortBy(out, ['weight:desc', 'label']));

      this.gettingGroups = false;
    },

    getProductsGroups(out, loadProducts, namespaceMode, productMap) {
      const clusterId = this.$store.getters['clusterId'];
      const currentType = this.$route.params.resource || '';

      for ( const productId of loadProducts ) {
        const modes = [TYPE_MODES.BASIC];

        if ( productId === NAVLINKS ) {
          continue;
        }

        if ( productId === EXPLORER ) {
          modes.push(TYPE_MODES.FAVORITE);
          modes.push(TYPE_MODES.USED);
        }

        const typesByMode = this.$store.getters['type-map/allTypes'](productId, modes);

        for ( const mode of modes ) {
          const types = typesByMode[mode] || {};
          const more = this.$store.getters['type-map/getTree'](productId, mode, types, clusterId, namespaceMode, currentType);

          if ( productId === EXPLORER || !this.isExplorer ) {
            addObjects(out, more);
          } else {
            const root = more.find((x) => x.name === 'root');
            const other = more.filter((x) => x.name !== 'root');

            const group = {
              name:     productId,
              label:    this.$store.getters['i18n/withFallback'](`product.${ productId }`, null, ucFirst(productId)),
              children: [...(root?.children || []), ...other],
              weight:   productMap[productId]?.weight || 0,
            };

            addObject(out, group);
          }
        }
      }
    },

    getExplorerGroups(out) {
      if ( this.isExplorer ) {
        const allNavLinks = this.allNavLinks;
        const toAdd = [];
        const haveGroup = {};

        for ( const obj of allNavLinks ) {
          if ( !obj.link ) {
            continue;
          }

          const groupLabel = obj.spec.group;
          const groupSlug = obj.normalizedGroup;

          const entry = {
            name:        `link-${ obj._key }`,
            link:        obj.link,
            target:      obj.actualTarget,
            label:       obj.labelDisplay,
            sideLabel:   obj.spec.sideLabel,
            iconSrc:     obj.spec.iconSrc,
            description: obj.spec.description,
          };

          if ( groupSlug ) {
            if ( haveGroup[groupSlug] ) {
              continue;
            }

            haveGroup[groupSlug] = true;

            toAdd.push({
              name:     `navlink-group-${ groupSlug }`,
              label:    groupLabel,
              isRoot:   true,
              children: [
                {
                  name:  `navlink-child-${ groupSlug }`,
                  label: groupLabel,
                  route: {
                    name:   'c-cluster-navlinks-group',
                    params: {
                      cluster: this.clusterId,
                      group:   groupSlug,
                    }
                  },
                }
              ],
              weight: -100,
            });
          } else {
            toAdd.push({
              name:     `navlink-${ entry.name }`,
              label:    entry.label,
              isRoot:   true,
              children: [entry],
              weight:   -100,
            });
          }
        }

        addObjects(out, toAdd);
      }
    },

    groupSelected(selected) {
      this.$refs.groups.forEach((grp) => {
        if (grp.canCollapse) {
          grp.isExpanded = (grp.group.name === selected.name);
        }
      });
    },

    collapseAll() {
      this.$refs.groups.forEach((grp) => {
        grp.isExpanded = false;
      });
    },

    syncNav() {
      const refs = this.$refs.groups;

      if (refs) {
        let canExpand = true;
        const expanded = refs.filter((grp) => grp.isExpanded)[0];

        if (expanded && expanded.hasActiveRoute()) {
          this.$nextTick(() => expanded.syncNav());

          return;
        }
        refs.forEach((grp) => {
          if (!grp.group.isRoot) {
            grp.isExpanded = false;
            if (canExpand) {
              const isActive = grp.hasActiveRoute();

              if (isActive) {
                grp.isExpanded = true;
                canExpand = false;
                this.$nextTick(() => grp.syncNav());
              }
            }
          }
        });
      }
    },
  },
};
</script>

<template>
  <nav
    class="side-nav"
    role="navigation"
    :aria-label="t('nav.ariaLabel.sideNav')"
  >
    <div class="nav">
      <template
        v-for="(g) in groups"
        :key="g.name"
      >
        <Group
          ref="groups"
          id-prefix=""
          class="package"
          :group="g"
          :can-collapse="!g.isRoot"
          :show-header="!g.isRoot"
          @selected="groupSelected($event)"
          @expand="groupSelected($event)"
        />
      </template>
    </div>

    <div
      v-if="showProductFooter"
      class="footer"
    >
      <router-link
        :to="supportLink"
        class="pull-right"
        role="link"
        :aria-label="t('nav.support', {hasSupport: true})"
      >
        {{ t('nav.support', {hasSupport: true}) }}
      </router-link>
      <span
        v-clean-tooltip="{content: displayVersion, placement: 'top'}"
        class="clip version text-muted"
      >
        {{ displayVersion }}
      </span>
      <LocaleSelector
        v-if="isSingleProduct && hasMultipleLocales && !isStandaloneHarvester"
        mode="login"
        :show-icon="false"
      />
    </div>

    <div
      v-else
      class="version text-muted flex"
    >
      <router-link
        v-if="singleProductAbout"
        :to="singleProductAbout"
        role="link"
        :aria-label="t('nav.ariaLabel.productAboutPage')"
      >
        {{ displayVersion }}
      </router-link>
      <template v-else>
        <span
          v-if="isVirtualCluster && isExplorer"
          v-clean-tooltip="{content: harvesterVersion, placement: 'top'}"
          class="clip text-muted ml-5"
        >
          (Harvester-{{ harvesterVersion }})
        </span>
      </template>
    </div>
  </nav>
</template>

<style lang="scss" scoped>
// ─── DESIGN TOKENS ────────────────────────────────────────────────────────────
// Single source of truth for all sizing. Tune here, everything updates.
:root {
  --sn-font-size:      14px;   // unified font size for ALL nav rows (headers + items)
  --sn-font-weight:    500;    // normal rows
  --sn-font-weight-hd: 500;    // group headers — SAME weight as items (fixes font difference)
  --sn-item-height:    32px;   // exact row height (matches original design)
  --sn-item-px:        12px;   // horizontal padding inside each row
  --sn-item-gap:       12px;    // vertical gap between rows (matches spec)
  --sn-child-indent:   8px;    // extra left indent for items inside a group body
  --sn-radius:         8px;    // border-radius for all rows
  --sn-icon-size:      16px;   // icon box size
  --sn-icon-gap:       8px;    // gap between icon and label text
}

// ─── SHELL ────────────────────────────────────────────────────────────────────
.side-nav {
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  border-right: 1px solid var(--border);
  padding-bottom: 4px;

  > * {
    position: relative;
    z-index: 1;
  }

  .nav {
    flex: 1;
    overflow-y: auto;
    padding: 10px 8px;
  }
}

// ─── GROUP WRAPPER ────────────────────────────────────────────────────────────
// Space between top-level accordion groups = item gap (keeps rhythm consistent)
.side-nav :deep(.accordion) {
  margin-bottom: var(--sn-item-gap);
}

// ─── GROUP HEADER ─────────────────────────────────────────────────────────────
// "Networks", "Backup and Snapshots", "Monitoring & Logging", "Advanced"
//
// FIX 1 — font must be identical to leaf items:
//   font-size: var(--sn-font-size)  → 14px, same as .type-link
//   font-weight: var(--sn-font-weight-hd) → 500, same as .type-link
//   Previously the header had font-size: 13px + font-weight: 600 while items
//   had font-size: 14px + font-weight: 500 — that mismatch caused the visible
//   difference. Now both share the same token values.
//
// FIX 2 — height locked to 32px via min-height so headers and items are the
//   same box size.
//
// FIX 3 — text must NOT truncate (white-space: normal, no overflow: hidden,
//   no text-overflow: ellipsis on the h6). Long labels like
//   "Backup and Snapshots" must wrap or simply fit.
.side-nav :deep(.accordion .header) {
  display: flex;
  align-items: center;
  justify-content: space-between;

  min-height: var(--sn-item-height);  // 32px — same box as items
  padding: 0 var(--sn-item-px);
  border-radius: var(--sn-radius);

  // ↓ Unified typography — matches .type-link exactly
  font-size:   var(--sn-font-size);
  font-weight: var(--sn-font-weight-hd);
  line-height: 1.3;
  text-transform: none;
  letter-spacing: normal;

  color: var(--body-text);
  opacity: 0.8;                  // subtle mute so headers feel like organisers
  background: transparent;
  cursor: pointer;

  transition: background 0.15s ease, opacity 0.15s ease;

  &:hover {
    background: var(--nav-hover);
    opacity: 1;
    text-decoration: none;
  }
}

// Rancher injects an <h6> inside the header — strip all its own sizing so our
// parent rules take full effect. Also allow text to wrap (no truncation).
.side-nav :deep(.accordion .header h6) {
  margin: 0;
  font-size: inherit;
  font-weight: inherit;
  line-height: inherit;
  text-transform: none;

  white-space: normal;
  overflow: visible;
  text-overflow: unset;
  word-break: normal;
}

// Chevron icon in header — keep it visually light
.side-nav :deep(.toggle-accordion) {
  opacity: 0.5;
  flex-shrink: 0;
  margin-left: 4px;
}

// ─── GROUP BODY ───────────────────────────────────────────────────────────────
// NEVER set a background here — it would fuse all children into one block.
// Left indent visually nests children under their header.
// Top/bottom padding keeps breathing room equal to one item-gap.
.side-nav :deep(.accordion .body) {
  background: transparent;
  padding: var(--sn-item-gap) 0 var(--sn-item-gap) var(--sn-child-indent);
}

// ─── NAV ITEMS (leaf links) ───────────────────────────────────────────────────
// Every clickable route target — both root-level and inside a group.
//
// FIX 1 — height: 32px locked (same as header)
// FIX 2 — gap between rows: margin-bottom: 8px (var(--sn-item-gap))
// FIX 3 — label must NOT truncate: white-space: normal on .label
// FIX 4 — icon slot: a 16px icon box before the label
.side-nav :deep(.type-link) {
  display: flex;
  align-items: center;
  // justify-content: space-between keeps the count badge (⊞ 1) on the right
  justify-content: space-between;

  min-height: var(--sn-item-height);  // 32px
  padding: 0 var(--sn-item-px);
  border-radius: var(--sn-radius);

  font-size:   var(--sn-font-size);   // 14px — same as header
  font-weight: var(--sn-font-weight); // 500  — same as header
  line-height: 1.3;
  color: var(--body-text);

  margin-bottom: var(--sn-item-gap);  // 8px vertical gap between items
  transition: background 0.15s ease, color 0.15s ease;
  cursor: pointer;

  &:last-child {
    margin-bottom: 0;
  }

  &:hover {
    background: var(--nav-hover);
    text-decoration: none;
  }
}

// Active route pill
.side-nav :deep(.router-link-exact-active.type-link),
.side-nav :deep(.type-link.router-link-active) {
  background: var(--nav-active);
  font-weight: 600;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
}

// ─── LABEL TEXT ───────────────────────────────────────────────────────────────
// FIX: "Cluster Network Configuration" was being cut to "Cluster Network Configu..."
// Root cause was white-space: nowrap + overflow: hidden + text-overflow: ellipsis
// on .label. We remove ALL three constraints so the full text is always visible.
// The sidebar itself is wide enough; we just need to stop clipping it.
.side-nav :deep(.type-link .label) {
  flex: 1;
  min-width: 0;
  white-space: normal;
  overflow: visible;
  text-overflow: unset;
  word-break: normal;
  margin-top: 4px;
  margin-bottom: 4px;

}

// ─── ICONS ────────────────────────────────────────────────────────────────────
// Rancher/Harvester nav items already include an <i class="icon ..."> element
// inside .type-link. We size and position it consistently.
// For group headers the icon lives inside .header — same treatment.
//
// If a specific item has no icon from the framework, you can add one via
// CSS content on a ::before pseudo, keyed by data-type attribute, but that
// requires knowing the resource name. The rules below handle the existing icons.

// Icon inside leaf items
.side-nav :deep(.type-link > i),
.side-nav :deep(.type-link > .icon) {
  flex-shrink: 0;
  width:  var(--sn-icon-size);   // 16px
  height: var(--sn-icon-size);
  font-size: var(--sn-icon-size);
  line-height: var(--sn-icon-size);
  text-align: center;
  margin-right: var(--sn-icon-gap);  // 8px between icon and label
  opacity: 0.65;
}

// Active item — full opacity icon
.side-nav :deep(.router-link-exact-active.type-link > i),
.side-nav :deep(.router-link-exact-active.type-link > .icon) {
  opacity: 1;
}

// Icon inside group headers (chevron aside, there may be a type icon)
.side-nav :deep(.accordion .header > i),
.side-nav :deep(.accordion .header > .icon) {
  flex-shrink: 0;
  width:  var(--sn-icon-size);
  height: var(--sn-icon-size);
  font-size: var(--sn-icon-size);
  line-height: var(--sn-icon-size);
  text-align: center;
  margin-right: var(--sn-icon-gap);
  opacity: 0.6;
}

// Count badge (⊞ 2) — right-aligned, keep it small
.side-nav :deep(.type-link .count),
.side-nav :deep(.type-link .side-label) {
  flex-shrink: 0;
  font-size: 11px;
  opacity: 0.55;
  margin-left: 6px;
}

// ─── TOOLS BAR ────────────────────────────────────────────────────────────────
.side-nav .tools {
  display: flex;
  margin: 10px;
  text-align: center;

  A {
    align-items: center;
    border: 1px solid var(--border);
    border-radius: var(--sn-radius);
    color: var(--body-text);
    display: flex;
    justify-content: center;
    outline: 0;
    flex: 1;
    padding: 10px;
    transition: background 0.15s ease;

    &:hover {
      background: var(--nav-hover);
      text-decoration: none;
    }

    > I {
      margin-right: 4px;
    }
  }

  &.router-link-active:not(:hover) A {
    background-color: var(--nav-active);
  }
}

// ─── FOOTER ───────────────────────────────────────────────────────────────────
.side-nav .footer {
  margin: 16px 12px;
  display: flex;
  flex-direction: row;
  font-size: 12px;
  color: var(--body-text);
  opacity: 0.7;

  > * {
    flex: 1;
    text-align: center;

    &:first-child { text-align: left; }
    &:last-child  { text-align: right; }
  }

  .version {
    margin: 0;
    cursor: default;
  }

  .locale-chooser {
    cursor: pointer;
  }
}

.side-nav .version {
  cursor: default;
  margin: 0 10px 10px 10px;
}

.flex {
  display: flex;
}
</style>